import{_ as a,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/coushi-method.svg",e="/img/poshi-method.svg",l="/img/pingshi-method.svg",r="/img/cross-multi-logic.svg",o="/img/butterfly-method.svg",b=JSON.parse('{"title":"小学数学速算技巧全攻略：从基础加减到奥数级简算","description":"深度解析小学数学中常用的速算与简便计算技巧，涵盖十字相乘、蝴蝶法、近9乘法、乘11、裂项相消及等差数列求和等，助你建立强大的数感。","frontmatter":{"title":"小学数学速算技巧全攻略：从基础加减到奥数级简算","date":"2026-01-15T11:00:00.000Z","categories":["数学"],"tags":["小学数学","计算技巧","速算","凑整法","裂项相消"],"description":"深度解析小学数学中常用的速算与简便计算技巧，涵盖十字相乘、蝴蝶法、近9乘法、乘11、裂项相消及等差数列求和等，助你建立强大的数感。","cover":"/img/math-calc-tricks-advanced.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-calculation-tricks.md","filePath":"posts/primary-math-calculation-tricks.md","lastUpdated":null}'),c={name:"posts/primary-math-calculation-tricks.md"};function i(h,s,d,x,g,u){return n(),m("div",null,[...s[0]||(s[0]=[t('<h1 id="小学数学速算技巧全攻略-从基础到拔尖" tabindex="-1">小学数学速算技巧全攻略：从基础到拔尖 <a class="header-anchor" href="#小学数学速算技巧全攻略-从基础到拔尖" aria-label="Permalink to &quot;小学数学速算技巧全攻略：从基础到拔尖&quot;">​</a></h1><p>计算能力不仅是数学成绩的基石，更是锻炼逻辑思维、培养数感的最佳途径。在杭州乃至全国的高标准教育环境下，单纯的准确已不足够，<strong>速度与巧思</strong>才是拉开差距的关键。</p><p>本文将为您深度拆解小学数学中所有核心速算技巧，按照<strong>从基础启蒙到奥数拔尖</strong>的循序渐进路径，助您掌握数字背后的“捷径”。</p><hr><h2 id="一、-基础启蒙-20以内的计算神技-1-2年级" tabindex="-1">一、 基础启蒙：20以内的计算神技 (1-2年级) <a class="header-anchor" href="#一、-基础启蒙-20以内的计算神技-1-2年级" aria-label="Permalink to &quot;一、 基础启蒙：20以内的计算神技 (1-2年级)&quot;">​</a></h2><p>在学习复杂速算之前，必须打牢“凑十”的基础。这是所有高级算法的根基。</p><h3 id="_1-凑十法-coushi-method-进位加法的核心" tabindex="-1">1. 凑十法 (Coushi Method)：进位加法的核心 <a class="header-anchor" href="#_1-凑十法-coushi-method-进位加法的核心" aria-label="Permalink to &quot;1. 凑十法 (Coushi Method)：进位加法的核心&quot;">​</a></h3><p>适用于 20 以内的进位加法。核心思想是：<strong>拆小数，凑大数</strong>。</p><p><strong>【逻辑图解】</strong><img src="'+p+'" alt="凑十法逻辑图"></p><p><strong>计算步骤 (以 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mo>+</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">9 + 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">6</span></span></span></span> 为例)：</strong></p><ol><li><strong>看大数</strong>：9 还差 1 凑成 10。</li><li><strong>拆小数</strong>：把 6 拆成 1 和 5。</li><li><strong>凑成十</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">9 + 1 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>。</li><li><strong>加剩数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>+</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">10 + 5 = 15</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span></span></span></span>。</li></ol><p><strong>口诀</strong>：看大数，分小数，凑成十，加剩数。</p><hr><h3 id="_2-破十法-poshi-method-退位减法的利器" tabindex="-1">2. 破十法 (Poshi Method)：退位减法的利器 <a class="header-anchor" href="#_2-破十法-poshi-method-退位减法的利器" aria-label="Permalink to &quot;2. 破十法 (Poshi Method)：退位减法的利器&quot;">​</a></h3><p>当个位不够减时，向十位“借”一个 10。</p><p><strong>【逻辑图解】</strong><img src="'+e+'" alt="破十法逻辑图"></p><p><strong>计算步骤 (以 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>3</mn><mo>−</mo><mn>9</mn></mrow><annotation encoding="application/x-tex">13 - 9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mord mathrm">9</span></span></span></span> 为例)：</strong></p><ol><li><strong>拆大数</strong>：把 13 拆成 10 和 3。</li><li><strong>先减十</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>−</mo><mn>9</mn><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">10 - 9 = 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mord mathrm">1</span></span></span></span>。</li><li><strong>加剩数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">1 + 3 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span>。</li></ol><p><strong>口诀</strong>：减九加一，减八加二，减七加三，减六加四。</p><hr><h3 id="_3-平十法-pingshi-method-连续减法的艺术" tabindex="-1">3. 平十法 (Pingshi Method)：连续减法的艺术 <a class="header-anchor" href="#_3-平十法-pingshi-method-连续减法的艺术" aria-label="Permalink to &quot;3. 平十法 (Pingshi Method)：连续减法的艺术&quot;">​</a></h3><p>也叫“连减法”，核心是：<strong>先减到十，再减余数</strong>。</p><p><strong>【逻辑图解】</strong><img src="'+l+'" alt="平十法逻辑图"></p><p><strong>计算步骤 (以 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mo>−</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">15 - 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">8</span></span></span></span> 为例)：</strong></p><ol><li><strong>看尾数</strong>：15 的个位是 5。</li><li><strong>拆减数</strong>：把 8 拆成 5 和 3。</li><li><strong>连减法</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mo>−</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">15 - 5 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">10 - 3 = 7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">7</span></span></span></span>。</li></ol><hr><h3 id="_4-加减法速算-多加要减-多减要加" tabindex="-1">4. 加减法速算：“多加要减，多减要加” <a class="header-anchor" href="#_4-加减法速算-多加要减-多减要加" aria-label="Permalink to &quot;4. 加减法速算：“多加要减，多减要加”&quot;">​</a></h3><p>针对接近 10、100、1000 的数字（如 9, 99, 198 等）进行加减时，先凑整再修正。</p><p><strong>核心思想：</strong></p><ul><li><strong>加法修正</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>+</mo><mn>9</mn><mn>9</mn><mo>=</mo><mi>A</mi><mo>+</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">A + 99 = A + 100 - 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span></span></span></span></li><li><strong>减法修正</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>−</mo><mn>9</mn><mn>9</mn><mo>=</mo><mi>A</mi><mo>−</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">A - 99 = A - 100 + 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">−</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mord mathit">A</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span></span></span></span></li></ul><p><strong>示例：</strong></p><ul><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mn>8</mn><mo>+</mo><mn>9</mn><mn>9</mn><mo>=</mo><mn>1</mn><mn>5</mn><mn>8</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>1</mn><mo>=</mo><mn>2</mn><mn>5</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">158 + 99 = 158 + 100 - 1 = 257</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mord mathrm">7</span></span></span></span></li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>2</mn><mn>4</mn><mo>−</mo><mn>1</mn><mn>9</mn><mn>8</mn><mo>=</mo><mn>3</mn><mn>2</mn><mn>4</mn><mo>−</mo><mn>2</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">324 - 198 = 324 - 200 + 2 = 126</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">9</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">6</span></span></span></span></li></ul><hr><h2 id="二、-进阶口算-摆脱繁琐竖式-3-4年级" tabindex="-1">二、 进阶口算：摆脱繁琐竖式 (3-4年级) <a class="header-anchor" href="#二、-进阶口算-摆脱繁琐竖式-3-4年级" aria-label="Permalink to &quot;二、 进阶口算：摆脱繁琐竖式 (3-4年级)&quot;">​</a></h2><p>掌握了基础后，我们可以通过更高级的模型处理多位数运算。</p><h3 id="_1-十字相乘法-cross-multiplication" tabindex="-1">1. 十字相乘法 (Cross Multiplication) <a class="header-anchor" href="#_1-十字相乘法-cross-multiplication" aria-label="Permalink to &quot;1. 十字相乘法 (Cross Multiplication)&quot;">​</a></h3><p>适用于所有两位数乘法。通过图形化思维，将计算过程扁平化。</p><p><strong>【逻辑图解】</strong><img src="'+r+'" alt="十字相乘逻辑图"><em>(注：上图展示了“个位相乘”、“交叉相乘求和”、“十位相乘”的流转过程)</em></p><p><strong>计算步骤：</strong></p><ol><li><strong>个位相乘</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">3 \\times 4 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>（记 2，进 1）</li><li><strong>交叉求和</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>2</mn><mo>×</mo><mn>4</mn><mo>)</mo><mo>+</mo><mo>(</mo><mn>3</mn><mo>×</mo><mn>1</mn><mo>)</mo><mo>+</mo><mn>1</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">(2 \\times 4) + (3 \\times 1) + 1 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>（记 2，进 1）</li><li><strong>十位相乘</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>1</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">2 \\times 1 + 1 = 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span>（记 3） <strong>示例：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>3</mn><mo>×</mo><mn>1</mn><mn>4</mn><mo>=</mo><mn>3</mn><mn>2</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">23 \\times 14 = 322</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mord mathrm">2</span></span></span></span></strong></li></ol><hr><h3 id="_2-乘-11-111-1111-速算法-两头一拉-中间一加" tabindex="-1">2. 乘 11/111/1111 速算法：“两头一拉，中间一加” <a class="header-anchor" href="#_2-乘-11-111-1111-速算法-两头一拉-中间一加" aria-label="Permalink to &quot;2. 乘 11/111/1111 速算法：“两头一拉，中间一加”&quot;">​</a></h3><p>这是最神奇且最易掌握的技巧之一，其本质是“滑动累加”。</p><p><strong>【乘 11 规律】</strong> 将乘数的首尾拉开，中间填入各位数相加之和。</p><ul><li><strong>示例：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>5</mn><mo>×</mo><mn>1</mn><mn>1</mn><mo>=</mo><mn>4</mn><mo>(</mo><mn>4</mn><mo>+</mo><mn>5</mn><mo>)</mo><mn>5</mn><mo>=</mo><mn>4</mn><mn>9</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">45 \\times 11 = 4(4+5)5 = 495</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mclose">)</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">9</span><span class="mord mathrm">5</span></span></span></span></strong></li><li><strong>进位示例：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mn>7</mn><mo>×</mo><mn>1</mn><mn>1</mn><mo>=</mo><mn>8</mn><mo>(</mo><mn>8</mn><mo>+</mo><mn>7</mn><mo>)</mo><mn>7</mn><mo>=</mo><mn>9</mn><mn>5</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">87 \\times 11 = 8(8+7)7 = 957</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">8</span><span class="mopen">(</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">7</span><span class="mclose">)</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">5</span><span class="mord mathrm">7</span></span></span></span></strong></li></ul><p><strong>【乘 111/1111 规律】</strong> 从右向左，位数依次累加，累加个数不超过“1”的个数。</p><ul><li><strong>示例：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>3</mn><mo>×</mo><mn>1</mn><mn>1</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">123 \\times 111</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span></span></span></span></strong><ol><li>个位：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span></span></span></span></li><li>个+十：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">3+2=5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span></li><li>个+十+百：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>+</mo><mn>2</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">3+2+1=6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span></li><li>十+百：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">2+1=3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span></li><li>百位：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span></span></span></span></li></ol></li><li><strong>结果</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>3</mn><mn>6</mn><mn>5</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">13653</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mord mathrm">5</span><span class="mord mathrm">3</span></span></span></span></li></ul><hr><h3 id="_3-头同尾合十-与-尾同头合十" tabindex="-1">3. “头同尾合十”与“尾同头合十” <a class="header-anchor" href="#_3-头同尾合十-与-尾同头合十" aria-label="Permalink to &quot;3. “头同尾合十”与“尾同头合十”&quot;">​</a></h3><p>这是处理特定组合时的“核武器”。</p><ul><li><strong>头同尾合十</strong>（如 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>4</mn><mo>×</mo><mn>2</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">24 \\times 26</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mord mathrm">6</span></span></span></span>）：十位相同，个位加起来等于 10。 <ul><li><strong>口诀</strong>：头乘（头+1），尾乘尾。</li><li><strong>计算</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mo>(</mo><mn>2</mn><mo>+</mo><mn>1</mn><mo>)</mo><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">2 \\times (2+1) = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>，后接 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>6</mn><mo>=</mo><mn>2</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">4 \\times 6 = 24</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span></span></span></span>。结果：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mn>2</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">624</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span></span></span></span>。</li></ul></li><li><strong>尾同头合十</strong>（如 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>6</mn><mo>×</mo><mn>7</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">36 \\times 76</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">7</span><span class="mord mathrm">6</span></span></span></span>）：个位相同，十位加起来等于 10。 <ul><li><strong>口诀</strong>：头乘头加尾，尾乘尾。</li><li><strong>计算</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>×</mo><mn>7</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>2</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">3 \\times 7 + 6 = 27</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">7</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">7</span></span></span></span>，后接 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>×</mo><mn>6</mn><mo>=</mo><mn>3</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">6 \\times 6 = 36</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span></span></span></span>。结果：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>7</mn><mn>3</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">2736</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">7</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span></span></span></span>。</li></ul></li></ul><h3 id="_4-凑整与拆分-简便运算的灵魂" tabindex="-1">4. 凑整与拆分：简便运算的灵魂 <a class="header-anchor" href="#_4-凑整与拆分-简便运算的灵魂" aria-label="Permalink to &quot;4. 凑整与拆分：简便运算的灵魂&quot;">​</a></h3><p>这是所有简便运算中最基础也最核心的意识。</p><ul><li><p><strong>寻找“好朋友数” (Complementary Numbers)</strong>：</p><ul><li><strong><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">2 \\times 5 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span></strong></li><li><strong><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>2</mn><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">4 \\times 25 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span></strong></li><li><strong><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>×</mo><mn>1</mn><mn>2</mn><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">8 \\times 125 = 1000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span></strong></li><li><strong><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>7</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>1</mn><mn>1</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">37 \\times 3 = 111</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span></span></span></span></strong></li></ul></li><li><p><strong>补数法 (Near-round Numbers)</strong>：当数字接近整十、整百时，将其转化为整加/整减。</p><ul><li><strong>示例</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>9</mn><mn>8</mn><mo>×</mo><mn>3</mn><mn>5</mn><mo>=</mo><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>2</mn><mo>)</mo><mo>×</mo><mn>3</mn><mn>5</mn><mo>=</mo><mn>3</mn><mn>5</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>7</mn><mn>0</mn><mo>=</mo><mn>3</mn><mn>4</mn><mn>9</mn><mn>3</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">998 \\times 35 = (1000 - 2) \\times 35 = 35000 - 70 = 34930</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">4</span><span class="mord mathrm">9</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span></span></span></span></li><li><strong>示例</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>2</mn><mo>+</mo><mn>9</mn><mn>8</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>1</mn><mo>+</mo><mn>9</mn><mn>9</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>×</mo><mn>4</mn><mo>+</mo><mo>(</mo><mn>2</mn><mo>−</mo><mn>2</mn><mo>+</mo><mn>1</mn><mo>−</mo><mn>1</mn><mo>)</mo><mo>=</mo><mn>4</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">102 + 98 + 101 + 99 = 100 \\times 4 + (2 - 2 + 1 - 1) = 400</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span></li></ul></li><li><p><strong>乘 9/99/999 速算规律</strong>： 对于 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>×</mo><mn>9</mn><mn>9</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mn>9</mn></mrow><annotation encoding="application/x-tex">A \\times 99...9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">×</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">9</span></span></span></span>（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span></span></span></span> 个 9）：结果的前半部分是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">A - 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">−</span><span class="mord mathrm">1</span></span></span></span>，后半部分是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span></span></span></span> 的补数（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><msup><mn>0</mn><mi>n</mi></msup><mo>−</mo><mi>A</mi></mrow><annotation encoding="application/x-tex">10^n - A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord"><span class="mord mathrm">0</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathit">n</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">−</span><span class="mord mathit">A</span></span></span></span>）。</p><ul><li><strong>示例</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>7</mn><mn>3</mn><mo>×</mo><mn>9</mn><mn>9</mn><mo>=</mo><mo>(</mo><mn>7</mn><mn>3</mn><mo>−</mo><mn>1</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">73 \\times 99 = (73-1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">7</span><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mopen">(</span><span class="mord mathrm">7</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span> 连上 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>7</mn><mn>3</mn><mo>)</mo><mo>=</mo><mn>7</mn><mn>2</mn><mn>2</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">(100-73) = 7227</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">7</span><span class="mord mathrm">3</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">7</span><span class="mord mathrm">2</span><span class="mord mathrm">2</span><span class="mord mathrm">7</span></span></span></span></li><li><strong>示例</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>5</mn><mn>6</mn><mo>×</mo><mn>9</mn><mn>9</mn><mn>9</mn><mo>=</mo><mo>(</mo><mn>4</mn><mn>5</mn><mn>6</mn><mo>−</mo><mn>1</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">456 \\times 999 = (456-1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span> 连上 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>4</mn><mn>5</mn><mn>6</mn><mo>)</mo><mo>=</mo><mn>4</mn><mn>5</mn><mn>5</mn><mn>5</mn><mn>4</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">(1000-456) = 455544</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mord mathrm">6</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mord mathrm">5</span><span class="mord mathrm">5</span><span class="mord mathrm">4</span><span class="mord mathrm">4</span></span></span></span></li></ul></li><li><p><strong>相同多位数乘法 (特殊平方)</strong>：</p><ul><li><strong>3 系列</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>3</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><msup><mn>3</mn><mn>2</mn></msup><mo>=</mo><mn>1</mn><mn>1</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mn>1</mn><mn>0</mn><mn>8</mn><mn>8</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mn>8</mn><mn>9</mn></mrow><annotation encoding="application/x-tex">33...3^2 = 11...1088...89</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.8141079999999999em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">3</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord"><span class="mord mathrm">3</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">8</span><span class="mord mathrm">8</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">8</span><span class="mord mathrm">9</span></span></span></span>（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">n-1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span><span class="mbin">−</span><span class="mord mathrm">1</span></span></span></span> 个 1 和 8）</li><li><strong>6 系列</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mn>6</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><msup><mn>6</mn><mn>2</mn></msup><mo>=</mo><mn>4</mn><mn>4</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mn>4</mn><mn>3</mn><mn>5</mn><mn>5</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mn>5</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">66...6^2 = 44...4355...56</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.8141079999999999em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mord mathrm">6</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord"><span class="mord mathrm">6</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">4</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">4</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mord mathrm">5</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">5</span><span class="mord mathrm">6</span></span></span></span>（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">n-1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span><span class="mbin">−</span><span class="mord mathrm">1</span></span></span></span> 个 4 和 5）</li><li><strong>9 系列</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>9</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><msup><mn>9</mn><mn>2</mn></msup><mo>=</mo><mn>9</mn><mn>9</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mn>9</mn><mn>8</mn><mn>0</mn><mn>0</mn><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mn>0</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">99...9^2 = 99...9800...01</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.8141079999999999em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord"><span class="mord mathrm">9</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">9</span><span class="mord mathrm">8</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span></span></span></span>（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">n-1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span><span class="mbin">−</span><span class="mord mathrm">1</span></span></span></span> 个 9 和 0）</li></ul></li><li><p><strong>1 系列（回文数金字塔）</strong>： 当两个相同的“纯 1”多位数相乘时，结果呈现对称的回文结构。</p><ul><li><strong>规律</strong>：如果有 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span></span></span></span> 个 1，结果就从 1 数到 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span></span></span></span>，再数回 1。</li><li><strong>示例</strong>： <ul><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>1</mn><mo>×</mo><mn>1</mn><mn>1</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">11 \\times 11 = 121</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">1</span></span></span></span>（2 个 1，数到 2）</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>1</mn><mn>1</mn><mo>×</mo><mn>1</mn><mn>1</mn><mn>1</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>3</mn><mn>2</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">111 \\times 111 = 12321</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mord mathrm">1</span></span></span></span>（3 个 1，数到 3）</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mo>×</mo><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>3</mn><mn>4</mn><mn>3</mn><mn>2</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">1111 \\times 1111 = 1234321</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span><span class="mord mathrm">4</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mord mathrm">1</span></span></span></span>（4 个 1，数到 4）</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mo>×</mo><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>3</mn><mn>4</mn><mn>5</mn><mn>6</mn><mn>7</mn><mn>8</mn><mn>9</mn><mn>8</mn><mn>7</mn><mn>6</mn><mn>5</mn><mn>4</mn><mn>3</mn><mn>2</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">111111111 \\times 111111111 = 12345678987654321</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mord mathrm">6</span><span class="mord mathrm">7</span><span class="mord mathrm">8</span><span class="mord mathrm">9</span><span class="mord mathrm">8</span><span class="mord mathrm">7</span><span class="mord mathrm">6</span><span class="mord mathrm">5</span><span class="mord mathrm">4</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mord mathrm">1</span></span></span></span>（9 个 1，数到 9）</li></ul></li></ul></li></ul><hr><h2 id="三、-分数与比例-直观建模-4-5年级" tabindex="-1">三、 分数与比例：直观建模 (4-5年级) <a class="header-anchor" href="#三、-分数与比例-直观建模-4-5年级" aria-label="Permalink to &quot;三、 分数与比例：直观建模 (4-5年级)&quot;">​</a></h2><h3 id="_1-蝴蝶相乘法-butterfly-method" tabindex="-1">1. 蝴蝶相乘法 (Butterfly Method) <a class="header-anchor" href="#_1-蝴蝶相乘法-butterfly-method" aria-label="Permalink to &quot;1. 蝴蝶相乘法 (Butterfly Method)&quot;">​</a></h3><p>解决异分母分数加减法时，无需繁琐通分，直接可视化求解。</p><p><strong>【逻辑图解】</strong><img src="'+o+'" alt="蝴蝶相乘法原理图"></p><p><strong>示例：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mfrac><mrow><mn>1</mn></mrow><mrow><mn>3</mn></mrow></mfrac><mo>+</mo><mfrac><mrow><mn>2</mn></mrow><mrow><mn>5</mn></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{1}{3} + \\frac{2}{5}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.845108em;"></span><span class="strut bottom" style="height:1.190108em;vertical-align:-0.345em;"></span><span class="base textstyle uncramped"><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">3</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">+</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">5</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">2</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></strong></p><ol><li><strong>左翅膀</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">1 \\times 5 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span></li><li><strong>右翅膀</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">2 \\times 3 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span></li><li><strong>新分子</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">5 + 6 = 11</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span></span></span></span></li><li><strong>新分母</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">3 \\times 5 = 15</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span></span></span></span><strong>结果：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mfrac><mrow><mn>1</mn><mn>1</mn></mrow><mrow><mn>1</mn><mn>5</mn></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{11}{15}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.845108em;"></span><span class="strut bottom" style="height:1.190108em;vertical-align:-0.345em;"></span><span class="base textstyle uncramped"><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></strong></li></ol><hr><h2 id="四、-拔尖技巧-奥数级简算-5-6年级" tabindex="-1">四、 拔尖技巧：奥数级简算 (5-6年级) <a class="header-anchor" href="#四、-拔尖技巧-奥数级简算-5-6年级" aria-label="Permalink to &quot;四、 拔尖技巧：奥数级简算 (5-6年级)&quot;">​</a></h2><h3 id="_1-裂项相消-partial-fractions" tabindex="-1">1. 裂项相消 (Partial Fractions) <a class="header-anchor" href="#_1-裂项相消-partial-fractions" aria-label="Permalink to &quot;1. 裂项相消 (Partial Fractions)&quot;">​</a></h3><p>当分母是两个连续整数或等差数列的乘积时，可以将一个分数拆分为两个分数之差。</p><p><strong>【核心公式】</strong></p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mfrac><mrow><mn>1</mn></mrow><mrow><mi>n</mi><mo>(</mo><mi>n</mi><mo>+</mo><mn>1</mn><mo>)</mo></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mi>n</mi></mrow></mfrac><mo>−</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mi>n</mi><mo>+</mo><mn>1</mn></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{1}{n(n+1)} = \\frac{1}{n} - \\frac{1}{n+1} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.32144em;"></span><span class="strut bottom" style="height:2.25744em;vertical-align:-0.936em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathit">n</span><span class="mopen">(</span><span class="mord mathit">n</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span><span style="top:-0.2300000000000001em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mrel">=</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathit">n</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">−</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathit">n</span><span class="mbin">+</span><span class="mord mathrm">1</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></span></p><p><strong>典型例题</strong>：\\frac{1}{1\\times2} + \\frac{1}{2\\times3} + \\dots + \\frac{1}{99\\times100}</p><ul><li><strong>逻辑</strong>：(1 - \\frac{1}{2}) + (\\frac{1}{2} - \\frac{1}{3}) + \\dots + (\\frac{1}{99} - \\frac{1}{100})</li><li><strong>中间项全部消掉</strong>，只剩首尾：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mo>−</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>1</mn><mn>0</mn><mn>0</mn></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>9</mn><mn>9</mn></mrow><mrow><mn>1</mn><mn>0</mn><mn>0</mn></mrow></mfrac></mrow><annotation encoding="application/x-tex">1 - \\frac{1}{100} = \\frac{99}{100}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.845108em;"></span><span class="strut bottom" style="height:1.190108em;vertical-align:-0.345em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mbin">−</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">9</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></li></ul><hr><h3 id="_2-等差数列求和-gauss-sum" tabindex="-1">2. 等差数列求和 (Gauss Sum) <a class="header-anchor" href="#_2-等差数列求和-gauss-sum" aria-label="Permalink to &quot;2. 等差数列求和 (Gauss Sum)&quot;">​</a></h3><p>源于高斯天才的发现，解决连续变化的数字求和问题。</p><p><strong>【计算公式】</strong></p><ul><li><strong>和 = (首项 + 末项) <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>×</mo></mrow><annotation encoding="application/x-tex">\\times</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.58333em;"></span><span class="strut bottom" style="height:0.66666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord">×</span></span></span></span> 项数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>÷</mo></mrow><annotation encoding="application/x-tex">\\div</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.58333em;"></span><span class="strut bottom" style="height:0.66666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord">÷</span></span></span></span> 2</strong></li><li><strong>项数 = (末项 - 首项) <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>÷</mo></mrow><annotation encoding="application/x-tex">\\div</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.58333em;"></span><span class="strut bottom" style="height:0.66666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord">÷</span></span></span></span> 公差 + 1</strong></li></ul><p><strong>示例</strong>：1 + 4 + 7 + \\dots + 31</p><ul><li><strong>项数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>3</mn><mn>1</mn><mo>−</mo><mn>1</mn><mo>)</mo><mo>÷</mo><mn>3</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>1</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">(31 - 1) \\div 3 + 1 = 11</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">3</span><span class="mord mathrm">1</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span></span></span></span></li><li><strong>求和</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mo>+</mo><mn>3</mn><mn>1</mn><mo>)</mo><mo>×</mo><mn>1</mn><mn>1</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>7</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">(1 + 31) \\times 11 \\div 2 = 176</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">7</span><span class="mord mathrm">6</span></span></span></span></li></ul><hr><h2 id="五、-大数运算与稳健策略-高年级综合" tabindex="-1">五、 大数运算与稳健策略 (高年级综合) <a class="header-anchor" href="#五、-大数运算与稳健策略-高年级综合" aria-label="Permalink to &quot;五、 大数运算与稳健策略 (高年级综合)&quot;">​</a></h2><p>面对动辄 6 位数以上的运算，除了速算，更需要<strong>工程化</strong>的校验手段：</p><ol><li><strong>估算法 (Estimation)</strong>：先对大数进行四舍五入估算。例如 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mn>0</mn><mn>1</mn><mn>2</mn><mo>×</mo><mn>1</mn><mn>9</mn><mn>9</mn><mo>≈</mo><mn>5</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>×</mo><mn>2</mn><mn>0</mn><mn>0</mn><mo>=</mo><mn>1</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">5012 \\times 199 \\approx 5000 \\times 200 = 1,000,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.8388800000000001em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mrel">≈</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mpunct">,</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mpunct">,</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。如果你的结果只有 10 万，显然位数错了。</li><li><strong>末位校验 (Unit Check)</strong>：乘积的末位数字必然等于因数末位乘积的末位。</li><li><strong>分配律拆解</strong>：将复杂大数拆分为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mi>n</mi></mrow><annotation encoding="application/x-tex">100+n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathit">n</span></span></span></span> 或 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mi>n</mi></mrow><annotation encoding="application/x-tex">100-n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathit">n</span></span></span></span> 的形式。</li></ol><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>速算不是死记硬背口诀，而是对<strong>运算定律</strong>（交换律、结合律、分配律）的极致理解与灵活运用。</p><p><strong>建议学习路径：</strong></p><ol><li><strong>L1 (1-2年级)</strong>：掌握凑十、破十、平十法，熟记“好朋友数”。</li><li><strong>L2 (3-4年级)</strong>：练习十字相乘与乘 11 速算，形成数感。</li><li><strong>L3 (4-5年级)</strong>：学会蝴蝶法与补数思维。</li><li><strong>L4 (5-6年级)</strong>：进阶学习裂项与等差数列，应对复杂应用题。</li></ol><p>掌握了这些技巧，计算将不再是负担，而是你数学思维中跳动的音符。</p><hr>',87)])])}const k=a(c,[["render",i]]);export{b as __pageData,k as default};
